static char *read_all(void) {
    size_t cap = 1 << 16, len = 0;
    char *buf = malloc(cap);
    for (;;) {
        if (len + 1 >= cap) buf = realloc(buf, cap *= 2);
        size_t r = fread(buf + len, 1, cap - len - 1, stdin);
        if (r == 0) break;
        len += r;
    }
    buf[len] = '\0';
    return buf;
}

static char *first_line(char *s) {
    char *nl = strpbrk(s, "\r\n");
    if (nl) *nl = '\0';
    size_t n = strlen(s);
    while (n && s[n - 1] == ' ') s[--n] = '\0';
    return s;
}

int main(void) {
    char *s = first_line(read_all());
    printf("%d\n", solve(s));
    return 0;
}

